"""Curated taint source/sink tables for taint analysis.

This module extends the base TAINT_SOURCES / DANGEROUS_SINKS sets declared
in ``ida_mcp.tools.taint`` with broader Linux + Windows coverage that was
not historically part of the default set. The lists are designed to be:

* Conservative — only APIs that are *demonstrably* user-controlled input
  (sources) or demonstrably dangerous (sinks) are included.
* Module-agnostic — they cover glibc, POSIX, Linux syscalls, ntdll,
  wininet, winhttp, bcrypt, advapi32, kernel32, etc.
* Curated, not autogenerated — the goal is precision, not coverage.
* Designed to be extended at runtime from a BRON-style threat corpus via
  :func:`extend_taint_taxonomy_from_corpus`.

Keep entries lowercase for sources; sinks are keyed by name (case
preserved) with a "vuln_type" value.
"""
from __future__ import annotations

import re
from collections.abc import Iterable
from typing import Any, Dict, List, Set, Tuple

