# ── Runtime extensions from a threat corpus ──────────────────────────────────

_TAINT_SOURCES_EXTRA: Set[str] = set()
_DANGEROUS_SINKS_EXTRA: Dict[str, str] = {}
_YARA_TAINT_PATTERNS: Dict[str, str] = {}


def reset_taxonomy() -> None:
    """Clear all corpus-derived taint entries. Does not touch the curated tables."""
    _TAINT_SOURCES_EXTRA.clear()
    _DANGEROUS_SINKS_EXTRA.clear()
    _YARA_TAINT_PATTERNS.clear()


def get_extra_sinks() -> Dict[str, str]:
    return dict(_DANGEROUS_SINKS_EXTRA)


# ── Corpus → taxonomy extension ──────────────────────────────────────────────

# Pattern to extract ASCII/wide string literals from a YARA rule source
_YARA_STRING_LITERAL_RE = re.compile(
    r"""(?P<kind>"s?"|")(?P<value>(?:\\.|(?!(?P=kind))[^"\\])*)(?P=kind)|"""
    r"""(?P<w>/[^/\n\r]*/)""",
    re.DOTALL,
)
_YARA_HEX_TOKEN_RE = re.compile(r"\b[0-9A-Fa-f]{2,}(?: [0-9A-Fa-f]{2}){2,}\b")
# Common Windows API substring hints (used to triage YARA string literals)
_API_HINT_TOKENS = {
    # Windows
    "CreateProcess", "ShellExecute", "WinExec", "LoadLibrary", "GetProcAddress",
    "VirtualAlloc", "WriteProcessMemory", "CreateRemoteThread", "NtCreateThreadEx",
    "RegSetValue", "RegCreateKey", "CreateService", "OpenSCManager",
    "InternetOpen", "InternetConnect", "HttpSendRequest", "WinHttpOpen",
    "WSASocket", "WSAConnect", "WSARecv", "WSASend",
    "CryptEncrypt", "CryptDecrypt", "BCryptEncrypt", "BCryptDecrypt",
    "AdjustTokenPrivileges", "LookupPrivilegeValue", "LogonUser",
    "SetWindowsHookEx", "CreateToolhelp32Snapshot",
    "DeleteFile", "MoveFileEx", "CreateFile", "WriteFile",
    # Linux
    "system", "execve", "popen", "dlopen", "mmap", "mprotect",
    "recv", "recvfrom", "send", "sendto", "read", "write",
    "chroot", "setuid", "setgid", "mount",
}


def _extract_yara_string_literals(rule_source: str) -> List[str]:
    if not rule_source:
        return []
    out: List[str] = []
    for m in _YARA_STRING_LITERAL_RE.finditer(rule_source):
        value = m.group("value") or ""
        if value:
            out.append(value)
    return out


def extend_taint_taxonomy_from_corpus(
    corpus: Any,
    *,
    reset: bool = True,
    max_yara_rules: int = 2000,
    max_added_sources: int = 200,
    max_added_sinks: int = 400,
) -> Dict[str, int]:
    """Extend the taint taxonomy from YARA rules in a BRON-style corpus.

    Strategy:
      * For each YARA rule source, extract ASCII string literals and look
        for known API name hints (e.g. "CreateProcess", "execve").
      * If the rule source mentions such an API, add the API name to the
        dangerous-sink set with ``vuln_type="yara_match"`` so the user can
        see which APIs the rule flags in the binary.
      * Returns counts of how many sources/sinks were added. The
        ``yara_match`` vuln_type makes the rule a sink candidate (if a
        binary actually contains that API, the rule is more likely to
        fire).

    The corpus-derived *sources* extension is intentionally conservative:
    YARA rules typically describe what a binary *contains*, not what
    external input it consumes. Use the curated Linux/Windows source
    tables in :data:`LINUX_TAINT_SOURCES` and :data:`WINDOWS_TAINT_SOURCES`
    for the source side.
    """
    if corpus is None:
        return {"sources": 0, "sinks": 0, "yara_rules_scanned": 0}
    if reset:
        reset_taxonomy()
    added_sources = 0
    added_sinks = 0
    yara_scanned = 0
    for rule in list(corpus.yara_rules or [])[:max_yara_rules]:
        yara_scanned += 1
        source = (rule.get("source") or "").strip()
        if not source:
            continue
        for lit in _extract_yara_string_literals(source):
            for hint in _API_HINT_TOKENS:
                if hint in lit and hint not in _DANGEROUS_SINKS_EXTRA:
                    _DANGEROUS_SINKS_EXTRA[hint] = "yara_match"
                    added_sinks += 1
                    if added_sinks >= max_added_sinks:
                        break
            if added_sinks >= max_added_sinks:
                break
        if added_sinks >= max_added_sinks:
            break
    return {
        "sources": added_sources,
        "sinks": added_sinks,
        "yara_rules_scanned": yara_scanned,
    }


def apply_curated_taxonomy(
    base_sources: Iterable[str],
    base_sinks: Dict[str, str],
) -> Tuple[Set[str], Dict[str, str]]:
    """Return (sources, sinks) merged with both curated Linux+Windows tables
    and any corpus-derived extras. Use this from taint tools that want a
    one-shot merged view."""
    sources = set(base_sources) | set(_TAINT_SOURCES_EXTRA) | set(LINUX_TAINT_SOURCES) | set(WINDOWS_TAINT_SOURCES)
    sinks = dict(base_sinks)
    for k, v in _DANGEROUS_SINKS_EXTRA.items():
        sinks.setdefault(k, v)
    for k, v in LINUX_DANGEROUS_SINKS.items():
        sinks.setdefault(k, v)
    for k, v in WINDOWS_DANGEROUS_SINKS.items():
        sinks.setdefault(k, v)
    return sources, sinks
